  transactionalSession: ?any
) {
  schema = convertParseSchemaToMongoSchema(schema);
  const mongoUpdate = transformUpdate(className, update, schema);
  const mongoWhere = transformWhere(className, query, schema);
  return this._adaptiveCollection(className)
    .then(collection => collection.upsertOne(mongoWhere, mongoUpdate, transactionalSession))
    .catch(err => this.handleError(err));
}

// Executes a find. Accepts: className, query in Parse format, and { skip, limit, sort }.
find(
  className: string,
  schema: SchemaType,
  query: QueryType,
  {
    skip,
    limit,
    sort,
    keys,
    readPreference,
    hint,
    caseInsensitive,
    explain,
    comment,
  }: QueryOptions
): Promise<any> {
  validateExplainValue(explain);
  schema = convertParseSchemaToMongoSchema(schema);
  const mongoWhere = transformWhere(className, query, schema);
  const mongoSort = _.mapKeys(sort, (value, fieldName) =>
    transformKey(className, fieldName, schema)
  );
  const mongoKeys = _.reduce(
    keys,
    (memo, key) => {
      if (key === 'ACL') {
        memo['_rperm'] = 1;
        memo['_wperm'] = 1;
      } else {
        memo[transformKey(className, key, schema)] = 1;
      }
      return memo;
    },
    {}
  );

  // If we aren't requesting the `_id` field, we need to explicitly opt out
  // of it. Doing so in parse-server is unusual, but it can allow us to
  // optimize some queries with covering indexes.
  if (keys && !mongoKeys._id) {
    mongoKeys._id = 0;
  }

  readPreference = this._parseReadPreference(readPreference);
  return this.createTextIndexesIfNeeded(className, query, schema)
    .then(() => this._adaptiveCollection(className))
    .then(collection =>
      collection.find(mongoWhere, {
        skip,
        limit,
        sort: mongoSort,
        keys: mongoKeys,
        maxTimeMS: this._maxTimeMS,
        batchSize: this._batchSize,
        readPreference,
        hint,
        caseInsensitive,
        explain,
        comment,
      })
    )
    .then(objects => {
      if (explain) {
        return objects;
      }
      return objects.map(object => mongoObjectToParseObject(className, object, schema));
    })
    .catch(err => this.handleError(err));
}

ensureIndex(
  className: string,
  schema: SchemaType,
  fieldNames: string[],
  indexName: ?string,
  caseInsensitive: boolean = false,
  options?: Object = {}
): Promise<any> {
  schema = convertParseSchemaToMongoSchema(schema);
  const indexCreationRequest = {};
  const mongoFieldNames = fieldNames.map(fieldName => transformKey(className, fieldName, schema));
  mongoFieldNames.forEach(fieldName => {
    indexCreationRequest[fieldName] = options.indexType !== undefined ? options.indexType : 1;
  });

  const defaultOptions: Object = { background: true, sparse: true };
  const indexNameOptions: Object = indexName ? { name: indexName } : {};
  const ttlOptions: Object = options.ttl !== undefined ? { expireAfterSeconds: options.ttl } : {};
  const sparseOptions: Object = options.sparse !== undefined ? { sparse: options.sparse } : {};
  const caseInsensitiveOptions: Object = caseInsensitive
    ? { collation: MongoCollection.caseInsensitiveCollation() }
    : {};
  const partialFilterOptions: Object =
    options.partialFilterExpression !== undefined
      ? { partialFilterExpression: options.partialFilterExpression }
      : {};
  const indexOptions: Object = {
    ...defaultOptions,
    ...caseInsensitiveOptions,
    ...indexNameOptions,
    ...ttlOptions,
    ...sparseOptions,
    ...partialFilterOptions,
  };

  return this._adaptiveCollection(className)
    .then(collection =>
      collection._mongoCollection.createIndex(indexCreationRequest, indexOptions)
    )
    .catch(err => this.handleError(err));
}

// Create a unique index. Unique indexes on nullable fields are not allowed. Since we don't
// currently know which fields are nullable and which aren't, we ignore that criteria.
// As such, we shouldn't expose this function to users of parse until we have an out-of-band
// Way of determining if a field is nullable. Undefined doesn't count against uniqueness,
// which is why we use sparse indexes.
ensureUniqueness(className: string, schema: SchemaType, fieldNames: string[]) {
  schema = convertParseSchemaToMongoSchema(schema);
  const indexCreationRequest = {};
  const mongoFieldNames = fieldNames.map(fieldName => transformKey(className, fieldName, schema));
  mongoFieldNames.forEach(fieldName => {
    indexCreationRequest[fieldName] = 1;
  });
  return this._adaptiveCollection(className)
    .then(collection => collection._ensureSparseUniqueIndexInBackground(indexCreationRequest))
    .catch(error => {
      if (error.code === 11000) {
        throw new Parse.Error(
          Parse.Error.DUPLICATE_VALUE,
          'Tried to ensure field uniqueness for a class that already has duplicates.'
        );
      }
      throw error;
    })
    .catch(err => this.handleError(err));
}

// Creates a unique sparse index on _auth_data_<provider>.id to prevent
// race conditions during concurrent signups with the same authData.
ensureAuthDataUniqueness(provider: string) {
  return this._adaptiveCollection('_User')
    .then(collection =>
      collection._mongoCollection.createIndex(
        { [`_auth_data_${provider}.id`]: 1 },
        { unique: true, sparse: true, background: true, name: `_auth_data_${provider}_id` }
      )
    )
    .catch(error => {
      if (error.code === 11000) {
        throw new Parse.Error(
          Parse.Error.DUPLICATE_VALUE,
          'Tried to ensure field uniqueness for a class that already has duplicates.'
        );
      }
      // Ignore "index already exists with same name" or "index already exists with different options"
      if (error.code === 85 || error.code === 86) {
        return;
      }
      throw error;
    })
    .catch(err => this.handleError(err));
}

// Used in tests
_rawFind(className: string, query: QueryType) {
  return this._adaptiveCollection(className)
    .then(collection =>
      collection.find(query, {
        maxTimeMS: this._maxTimeMS,
        batchSize: this._batchSize,
      })
    )
    .catch(err => this.handleError(err));
}

// Executes a count.
count(
  className: string,
  schema: SchemaType,
  query: QueryType,
  readPreference: ?string,
  _estimate: ?boolean,
  hint: ?mixed,
  comment: ?string
) {
  schema = convertParseSchemaToMongoSchema(schema);
  readPreference = this._parseReadPreference(readPreference);
  return this._adaptiveCollection(className)
    .then(collection =>
      collection.count(transformWhere(className, query, schema, true), {
        maxTimeMS: this._maxTimeMS,
        readPreference,
        hint,
        comment,
      })
    )
    .catch(err => this.handleError(err));
}

distinct(className: string, schema: SchemaType, query: QueryType, fieldName: string) {
  schema = convertParseSchemaToMongoSchema(schema);
  const isPointerField = schema.fields[fieldName] && schema.fields[fieldName].type === 'Pointer';
  const transformField = transformKey(className, fieldName, schema);

  return this._adaptiveCollection(className)
    .then(collection =>
      collection.distinct(transformField, transformWhere(className, query, schema))
    )
    .then(objects => {
      objects = objects.filter(obj => obj != null);
      return objects.map(object => {
        if (isPointerField) {
          return transformPointerString(schema, fieldName, object);
        }
        return mongoObjectToParseObject(className, object, schema);
      });
    })
    .catch(err => this.handleError(err));
}

aggregate(
  className: string,
  schema: any,
  pipeline: any,
  readPreference: ?string,
  hint: ?mixed,
  explain?: boolean,
  comment: ?string,
  rawValues?: boolean,
  rawFieldNames?: boolean
) {
  validateExplainValue(explain);
  if (rawValues) {
    pipeline = EJSON.deserialize(pipeline);
  }
  let isPointerField = false;
  pipeline = pipeline.map(stage => {
    if (stage.$group) {
      stage.$group = this._parseAggregateGroupArgs(schema, stage.$group, rawFieldNames);
      if (
        stage.$group._id &&
        typeof stage.$group._id === 'string' &&
        stage.$group._id.indexOf('$_p_') >= 0
      ) {
        isPointerField = true;
      }
    }
    if (stage.$match) {
      stage.$match = this._parseAggregateArgs(schema, stage.$match, rawValues, rawFieldNames);
    }
    if (stage.$project) {
      stage.$project = this._parseAggregateProjectArgs(schema, stage.$project, rawValues, rawFieldNames);
    }
    if (stage.$geoNear && stage.$geoNear.query) {
      stage.$geoNear.query = this._parseAggregateArgs(schema, stage.$geoNear.query, rawValues, rawFieldNames);
    }
    return stage;
  });
  readPreference = this._parseReadPreference(readPreference);
  return this._adaptiveCollection(className)
    .then(collection =>
      collection.aggregate(pipeline, {
        readPreference,
        maxTimeMS: this._maxTimeMS,
        batchSize: this._batchSize,
        hint,
        explain,
        comment,

          comment,
        })
      )
      .then(results => {
        if (rawFieldNames) {
          return results;
        }
        results.forEach(result => {
          if (Object.prototype.hasOwnProperty.call(result, '_id')) {
            if (isPointerField && result._id) {
              result._id = result._id.split('$')[1];
            }
            if (
              result._id == null ||
              result._id == undefined ||
              (['object', 'string'].includes(typeof result._id) && _.isEmpty(result._id))
            ) {
              result._id = null;
            }
            result.objectId = result._id;
            delete result._id;
          }
        });
        return results;
      })
      .then(objects => {
        if (rawValues) {
          return objects.map(obj => EJSON.serialize(obj));
        }
        if (rawFieldNames) {
          return objects;
        }
        return objects.map(object => mongoObjectToParseObject(className, object, schema));
      })
      .catch(err => this.handleError(err));
  }

  // This function will recursively traverse the pipeline and convert any Pointer or Date columns.
  // If we detect a pointer column we will rename the column being queried for to match the column
  // in the database. We also modify the value to what we expect the value to be in the database
  // as well.
  // For dates, the driver expects a Date object, but we have a string coming in. So we'll convert
  // the string to a Date so the driver can perform the necessary comparison.
  //
  // The goal of this method is to look for the "leaves" of the pipeline and determine if it needs
  // to be converted. The pipeline can have a few different forms. For more details, see:
  //     https://docs.mongodb.com/manual/reference/operator/aggregation/
  //
  // If the pipeline is an array, it means we are probably parsing an '$and' or '$or' operator. In
  // that case we need to loop through all of it's children to find the columns being operated on.
  // If the pipeline is an object, then we'll loop through the keys checking to see if the key name
  // matches one of the schema columns. If it does match a column and the column is a Pointer or
  // a Date, then we'll convert the value as described above.
  //
  // As much as I hate recursion...this seemed like a good fit for it. We're essentially traversing
  // down a tree to find a "leaf node" and checking to see if it needs to be converted.
  _parseAggregateArgs(schema: any, pipeline: any, rawValues?: boolean, rawFieldNames?: boolean): any {
    if (pipeline === null) {
      return null;
    } else if (Utils.isDate(pipeline)) {
      return pipeline;
    } else if (Array.isArray(pipeline)) {
      return pipeline.map(value => this._parseAggregateArgs(schema, value, rawValues, rawFieldNames));
    } else if (typeof pipeline === 'object') {
      const returnValue = {};
      for (const field in pipeline) {
        if (!rawFieldNames && schema.fields[field] && schema.fields[field].type === 'Pointer') {
          if (typeof pipeline[field] === 'object') {
            returnValue[`_p_${field}`] = pipeline[field];
          } else if (rawValues) {
            returnValue[`_p_${field}`] = pipeline[field];
          } else {
            returnValue[`_p_${field}`] = `${schema.fields[field].targetClass}$${pipeline[field]}`;
          }
        } else if (schema.fields[field] && schema.fields[field].type === 'Date' && !rawValues) {
          returnValue[field] = this._convertToDate(pipeline[field]);
        } else {
          returnValue[field] = this._parseAggregateArgs(schema, pipeline[field], rawValues, rawFieldNames);
        }

        if (!rawFieldNames) {
          if (field === 'objectId') {
            returnValue['_id'] = returnValue[field];
            delete returnValue[field];
          } else if (field === 'createdAt') {
            returnValue['_created_at'] = returnValue[field];
            delete returnValue[field];
          } else if (field === 'updatedAt') {
            returnValue['_updated_at'] = returnValue[field];
            delete returnValue[field];
          }
        }
      }
      return returnValue;
    }
    return pipeline;
  }

  // This function is slightly different than the one above. Rather than trying to combine these
  // two functions and making the code even harder to understand, I decided to split it up. The
  // difference with this function is we are not transforming the values, only the keys of the
  // pipeline.
  _parseAggregateProjectArgs(schema: any, pipeline: any, rawValues?: boolean, rawFieldNames?: boolean): any {
    const returnValue = {};
    for (const field in pipeline) {
      if (!rawFieldNames && schema.fields[field] && schema.fields[field].type === 'Pointer') {
        returnValue[`_p_${field}`] = pipeline[field];
      } else {
        returnValue[field] = this._parseAggregateArgs(schema, pipeline[field], rawValues, rawFieldNames);
      }

      if (!rawFieldNames) {
        if (field === 'objectId') {
          returnValue['_id'] = returnValue[field];
          delete returnValue[field];
        } else if (field === 'createdAt') {
          returnValue['_created_at'] = returnValue[field];
          delete returnValue[field];
        } else if (field === 'updatedAt') {
          returnValue['_updated_at'] = returnValue[field];
          delete returnValue[field];
        }
      }
    }
    return returnValue;
  }

  // This function is slightly different than the two above. MongoDB $group aggregate looks like:
  //     { $group: { _id: <expression>, <field1>: { <accumulator1> : <expression1> }, ... } }
  // The <expression> could be a column name, prefixed with the '$' character. We'll look for
  // these <expression> and check to see if it is a 'Pointer' or if it's one of createdAt,
  // updatedAt or objectId and change it accordingly.
  _parseAggregateGroupArgs(schema: any, pipeline: any, rawFieldNames?: boolean): any {
    if (Array.isArray(pipeline)) {
      return pipeline.map(value => this._parseAggregateGroupArgs(schema, value, rawFieldNames));
    } else if (typeof pipeline === 'object') {
      const returnValue = {};
      for (const field in pipeline) {
        returnValue[field] = this._parseAggregateGroupArgs(schema, pipeline[field], rawFieldNames);
      }
      return returnValue;
    } else if (typeof pipeline === 'string' && !rawFieldNames) {
      const field = pipeline.substring(1);
      if (schema.fields[field] && schema.fields[field].type === 'Pointer') {
        return `$_p_${field}`;
      } else if (field == 'createdAt') {
        return '$_created_at';
      } else if (field == 'updatedAt') {
        return '$_updated_at';
      }
    }
    return pipeline;
  }

  /**
   * Recursively converts values to Date objects. Since the passed object is part of an aggregation
   * pipeline and can contain various logic operators (like $gt, $lt, etc), this function will
   * traverse the object and convert any strings that can be parsed as dates into Date objects.
   * @param {any} value The value to convert.
   * @returns {any} The original value if not convertible to Date, or a Date object if it is.
   */
  _convertToDate(value: any): any {
    if (Utils.isDate(value)) {
      return value;
    }
    if (typeof value === 'string') {
      return isNaN(Date.parse(value)) ? value : new Date(value);
    }
    if (typeof value === 'object') {
      const returnValue = {};
      for (const field in value) {
        returnValue[field] = this._convertToDate(value[field]);
      }
      return returnValue;
    }
    return value;
  }

  _parseReadPreference(readPreference: ?string): ?string {
    if (readPreference) {
      readPreference = readPreference.toUpperCase();
    }
    switch (readPreference) {
      case 'PRIMARY':
        readPreference = ReadPreference.PRIMARY;
        break;
      case 'PRIMARY_PREFERRED':
        readPreference = ReadPreference.PRIMARY_PREFERRED;
        break;
      case 'SECONDARY':
        readPreference = ReadPreference.SECONDARY;
        break;
      case 'SECONDARY_PREFERRED':
        readPreference = ReadPreference.SECONDARY_PREFERRED;
        break;
      case 'NEAREST':
        readPreference = ReadPreference.NEAREST;
        break;
      case undefined:
      case null:
      case '':
        break;
      default:
        throw new Parse.Error(Parse.Error.INVALID_QUERY, 'Not supported read preference.');
    }
    return readPreference;
  }

  performInitialization(): Promise<void> {
    return Promise.resolve();
  }

  createIndex(className: string, index: any) {
    return this._adaptiveCollection(className)
      .then(collection => collection._mongoCollection.createIndex(index))
      .catch(err => this.handleError(err));
  }

  createIndexes(className: string, indexes: any) {
    return this._adaptiveCollection(className)
      .then(collection => collection._mongoCollection.createIndexes(indexes))
      .catch(err => this.handleError(err));
  }

  createIndexesIfNeeded(className: string, fieldName: string, type: any) {
    if (type && type.type === 'Polygon') {
      const index = {
        [fieldName]: '2dsphere',
      };
      return this.createIndex(className, index);
    }
    return Promise.resolve();
  }

  createTextIndexesIfNeeded(className: string, query: QueryType, schema: any): Promise<void> {
    for (const fieldName in query) {
      if (!query[fieldName] || !query[fieldName].$text) {
        continue;
      }
      const existingIndexes = schema.indexes;
      for (const key in existingIndexes) {
        const index = existingIndexes[key];
        if (Object.prototype.hasOwnProperty.call(index, fieldName)) {
          return Promise.resolve();
        }
      }
      const indexName = `${fieldName}_text`;
      const textIndex = {
        [indexName]: { [fieldName]: 'text' },
      };
      return this.setIndexesWithSchemaFormat(
        className,
        textIndex,
        existingIndexes,
        schema.fields
      ).catch(error => {
        if (error.code === 85) {
          // Index exist with different options
          return this.setIndexesFromMongo(className);
        }
        throw error;
      });
    }
    return Promise.resolve();
  }

  getIndexes(className: string) {
    return this._adaptiveCollection(className)
      .then(collection => collection._mongoCollection.indexes())
      .catch(err => this.handleError(err));
  }

  dropIndex(className: string, index: any) {
    return this._adaptiveCollection(className)
      .then(collection => collection._mongoCollection.dropIndex(index))
      .catch(err => this.handleError(err));
  }

  dropAllIndexes(className: string) {
    return this._adaptiveCollection(className)
      .then(collection => collection._mongoCollection.dropIndexes())
      .catch(err => this.handleError(err));
  }

  updateSchemaWithIndexes(): Promise<any> {
    return this.getAllClasses()
      .then(classes => {
        const promises = classes.map(schema => {
          return this.setIndexesFromMongo(schema.className);
        });
        return Promise.all(promises);
      })
      .catch(err => this.handleError(err));
  }

  createTransactionalSession(): Promise<any> {
    const transactionalSection = this.client.startSession();
    transactionalSection.startTransaction();
    return Promise.resolve(transactionalSection);
  }

  commitTransactionalSession(transactionalSection: any): Promise<void> {
    const commit = retries => {
      return transactionalSection
        .commitTransaction()
        .catch(error => {
          if (error && error.hasErrorLabel('TransientTransactionError') && retries > 0) {
            return commit(retries - 1);
          }
          throw error;
        })
        .then(() => {
          transactionalSection.endSession();
        });
    };
    return commit(5);
  }

  abortTransactionalSession(transactionalSection: any): Promise<void> {
    return transactionalSection.abortTransaction().then(() => {
      transactionalSection.endSession();
    });
  }
}

