// TODO: As yet not particularly well specified. Creates an object. Maybe shouldn't even need the schema,
// and should infer from the type. Or maybe does need the schema for validations. Or maybe needs
// the schema only for the legacy mongo format. We'll figure that out later.
createObject(className: string, schema: SchemaType, object: any, transactionalSession: ?any) {
  schema = convertParseSchemaToMongoSchema(schema);
  const mongoObject = parseObjectToMongoObjectForCreate(className, object, schema);
  return this._adaptiveCollection(className)
    .then(collection => collection.insertOne(mongoObject, transactionalSession))
    .then(() => ({ ops: [mongoObject] }))
    .catch(error => {
      if (error.code === 11000) {
        logger.error('Duplicate key error:', error.message);
        const err = new Parse.Error(
          Parse.Error.DUPLICATE_VALUE,
          'A duplicate value for a field with unique values was provided'
        );
        err.underlyingError = error;
        if (error.message) {
          const matches = error.message.match(/index:[\sa-zA-Z0-9_\-\.]+\$?([a-zA-Z_-]+)_1/);
          if (matches && Array.isArray(matches)) {
            err.userInfo = { duplicated_field: matches[1] };
          }
          // Check for authData unique index violations
          if (!err.userInfo) {
            const authDataMatch = error.message.match(/index:\s+(_auth_data_[a-zA-Z0-9_]+_id)/);
            if (authDataMatch) {
              err.userInfo = { duplicated_field: authDataMatch[1] };
            }
          }
        }
        throw err;
      }
      throw error;
    })
    .catch(err => this.handleError(err));
}

// Remove all objects that match the given Parse Query.
// If no objects match, reject with OBJECT_NOT_FOUND. If objects are found and deleted, resolve with undefined.
// If there is some other error, reject with INTERNAL_SERVER_ERROR.
deleteObjectsByQuery(
  className: string,
  schema: SchemaType,
  query: QueryType,
  transactionalSession: ?any
) {
  schema = convertParseSchemaToMongoSchema(schema);
  return this._adaptiveCollection(className)
    .then(collection => {
      const mongoWhere = transformWhere(className, query, schema);
      return collection.deleteMany(mongoWhere, transactionalSession);
    })
    .catch(err => this.handleError(err))
    .then(
      ({ deletedCount }) => {
        if (deletedCount === 0) {
          throw new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, 'Object not found.');

find(
  className: string,
  schema: SchemaType,
  query: QueryType,
  {
    skip,
    limit,
    sort,
    keys,
    readPreference,
    hint,
    caseInsensitive,
    explain,
    comment,
  }: QueryOptions
): Promise<any> {
  validateExplainValue(explain);
  schema = convertParseSchemaToMongoSchema(schema);
  const mongoWhere = transformWhere(className, query, schema);
  const mongoSort = _.mapKeys(sort, (value, fieldName) =>
    transformKey(className, fieldName, schema)
  );
  const mongoKeys = _.reduce(
    keys,
    (memo, key) => {
      if (key === 'ACL') {
        memo['_rperm'] = 1;
        memo['_wperm'] = 1;
      } else {
        memo[transformKey(className, key, schema)] = 1;
      }
      return memo;
    },
    {}
  );

  // If we aren't requesting the `_id` field, we need to explicitly opt out
  // of it. Doing so in parse-server is unusual, but it can allow us to
  // optimize some queries with covering indexes.
  if (keys && !mongoKeys._id) {
    mongoKeys._id = 0;
  }

  readPreference = this._parseReadPreference(readPreference);
  return this.createTextIndexesIfNeeded(className, query, schema)
    .then(() => this._adaptiveCollection(className))
    .then(collection =>
      collection.find(mongoWhere, {
        skip,
        limit,
        sort: mongoSort,
        keys: mongoKeys,
        maxTimeMS: this._maxTimeMS,
        batchSize: this._batchSize,
        readPreference,
        hint,
        caseInsensitive,
        explain,
        comment,
      })
    )
    .then(objects => {
      if (explain) {
        return objects;
      }
      return objects.map(object => mongoObjectToParseObject(className, object, schema));
    })
    .catch(err => this.handleError(err));
}

ensureIndex(
  className: string,
  schema: SchemaType,
  fieldNames: string[],
  indexName: ?string,
  caseInsensitive: boolean = false,
  options?: Object = {}
): Promise<any> {
  schema = convertParseSchemaToMongoSchema(schema);
  const indexCreationRequest = {};
  const mongoFieldNames = fieldNames.map(fieldName => transformKey(className, fieldName, schema));
  mongoFieldNames.forEach(fieldName => {
    indexCreationRequest[fieldName] = options.indexType !== undefined ? options.indexType : 1;
  });

  const defaultOptions: Object = { background: true, sparse: true };
  const indexNameOptions: Object = indexName ? { name: indexName } : {};
  const ttlOptions: Object = options.ttl !== undefined ? { expireAfterSeconds: options.ttl } : {};
  const sparseOptions: Object = options.sparse !== undefined ? { sparse: options.sparse } : {};
  const caseInsensitiveOptions: Object = caseInsensitive
    ? { collation: MongoCollection.caseInsensitiveCollation() }
    : {};
  const partialFilterOptions: Object =
    options.partialFilterExpression !== undefined
      ? { partialFilterExpression: options.partialFilterExpression }
      : {};
  const indexOptions: Object = {
    ...defaultOptions,
    ...caseInsensitiveOptions,
    ...indexNameOptions,
    ...ttlOptions,
    ...sparseOptions,
    ...partialFilterOptions,
  };

  return this._adaptiveCollection(className)
    .then(collection =>
      collection._mongoCollection.createIndex(indexCreationRequest, indexOptions)
    )
    .catch(err => this.handleError(err));
}

// Create a unique index. Unique indexes on nullable fields are not allowed. Since we don't
// currently know which fields are nullable and which aren't, we ignore that criteria.
// As such, we shouldn't expose this function to users of parse until we have an out-of-band
// Way of determining if a field is nullable. Undefined doesn't count against uniqueness,
// which is why we use sparse indexes.
ensureUniqueness(className: string, schema: SchemaType, fieldNames: string[]) {
  schema = convertParseSchemaToMongoSchema(schema);
  const indexCreationRequest = {};
  const mongoFieldNames = fieldNames.map(fieldName => transformKey(className, fieldName, schema));
  mongoFieldNames.forEach(fieldName => {
    indexCreationRequest[fieldName] = 1;
  });
  return this._adaptiveCollection(className)
    .then(collection => collection._ensureSparseUniqueIndexInBackground(indexCreationRequest))
    .catch(error => {
      if (error.code === 11000) {
        throw new Parse.Error(
          Parse.Error.DUPLICATE_VALUE,
          'Tried to ensure field uniqueness for a class that already has duplicates.'
        );
      }
      throw error;
    })
    .catch(err => this.handleError(err));
}

// Creates a unique sparse index on _auth_data_<provider>.id to prevent
// race conditions during concurrent signups with the same authData.
ensureAuthDataUniqueness(provider: string) {
  return this._adaptiveCollection('_User')
    .then(collection =>
      collection._mongoCollection.createIndex(
        { [`_auth_data_${provider}.id`]: 1 },
        { unique: true, sparse: true, background: true, name: `_auth_data_${provider}_id` }
      )
    )
    .catch(error => {
      if (error.code === 11000) {
        throw new Parse.Error(
          Parse.Error.DUPLICATE_VALUE,
          'Tried to ensure field uniqueness for a class that already has duplicates.'
        );
      }
      // Ignore "index already exists with same name" or "index already exists with different options"
      if (error.code === 85 || error.code === 86) {
        return;
      }
      throw error;
    })
    .catch(err => this.handleError(err));
}

// Used in tests
_rawFind(className: string, query: QueryType) {
