{"command": "cat > test/Adapters/Storage/Mongo/MongoTransform.test.js <<'EOF'
import Parse from 'parse/node';
import {
  transformKey,
  transformWhere,
  parseObjectToMongoObjectForCreate,
  transformUpdate,
  mongoObjectToParseObject,
  transformConstraint,
  transformPointerString,
} from '../../../../src/Adapters/Storage/Mongo/MongoTransform';

const schema = {
  fields: {
    name: { type: 'String' },
    score: { type: 'Number' },
    active: { type: 'Boolean' },
    publishedAt: { type: 'Date' },
    tags: { type: 'Array' },
    owner: { type: 'Pointer', targetClass: '_User' },
    comments: { type: 'Relation', targetClass: 'Comment' },
    file: { type: 'File' },
    location: { type: 'GeoPoint' },
    area: { type: 'Polygon' },
    data: { type: 'Object' },
  },
};

describe('transformKey', () => {
  it('maps Parse built-in names to their legacy Mongo columns', () => {
    expect(transformKey('_User', 'objectId', schema)).toBe('_id');
    expect(transformKey('_User', 'createdAt', schema)).toBe('_created_at');
    expect(transformKey('_User', 'updatedAt', schema)).toBe('_updated_at');
    expect(transformKey('_User', 'sessionToken', schema)).toBe('_session_token');
    expect(transformKey('_User', 'lastUsed', schema)).toBe('_last_used');
    expect(transformKey('_User', 'timesUsed', schema)).toBe('times_used');
  });

  it('prefixes pointer fields and leaves ordinary fields untouched', () => {
    expect(transformKey('Post', 'owner', schema)).toBe('_p_owner');
    expect(transformKey('Post', 'name', schema)).toBe('name');
    expect(
      transformKey('Post', 'legacyPointer', {
        fields: { legacyPointer: { __type: 'Pointer', targetClass: '_User' } },
      })
    ).toBe('_p_legacyPointer');
  });
});

describe('transformWhere', () => {
  it('transforms built-in ids, timestamps and ordinary constraints', () => {
    const result = transformWhere(
      'Post',
      {
        objectId: 'abc',
        createdAt: { $gte: '2024-01-02T03:04:05.000Z' },
        score: { $gt: 10 },
      },
      schema
    );

    expect(result.objectId).toBeUndefined();
    expect(result._id).toBe('abc');
    expect(result._created_at.$gte).toEqual(new Date('2024-01-02T03:04:05.000Z'));
    expect(result.score).toEqual({ $gt: 10 });
  });

  it('transforms pointer constraints and preserves nested query keys', () => {
    const result = transformWhere(
      'Post',
