describe('transformKey', () => {
  it('maps Parse built-in names to their legacy Mongo columns', () => {
    expect(transformKey('_User', 'objectId', schema)).toBe('_id');
    expect(transformKey('_User', 'createdAt', schema)).toBe('_created_at');
    expect(transformKey('_User', 'updatedAt', schema)).toBe('_updated_at');
    expect(transformKey('_User', 'sessionToken', schema)).toBe('_session_token');
    expect(transformKey('_User', 'lastUsed', schema)).toBe('_last_used');
    expect(transformKey('_User', 'timesUsed', schema)).toBe('times_used');
  });

  it('prefixes pointer fields and leaves ordinary fields untouched', () => {
    expect(transformKey('Post', 'owner', schema)).toBe('_p_owner');
    expect(transformKey('Post', 'name', schema)).toBe('name');
    expect(
      transformKey('Post', 'legacyPointer', {
        fields: { legacyPointer: { __type: 'Pointer', targetClass: '_User' } },
      })
    ).toBe('_p_legacyPointer');
  });
});

describe('transformWhere', () => {
  it('transforms built-in ids, timestamps and ordinary constraints', () => {
    const result = transformWhere(
      'Post',
      {
        objectId: 'abc',
        createdAt: { $gte: '2024-01-02T03:04:05.000Z' },
        score: { $gt: 10 },
      },
      schema
    );

    expect(result.objectId).toBeUndefined();
    expect(result._id).toBe('abc');
    expect(result._created_at.$gte).toEqual(new Date('2024-01-02T03:04:05.000Z'));
    expect(result.score).toEqual({ $gt: 10 });
  });

  it('transforms pointer constraints and preserves nested query keys', () => {
    const result = transformWhere(
      'Post',
      {
        owner: { __type: 'Pointer', className: '_User', objectId: 'u1' },
        'data.score': { $lte: 5 },
      },
      schema
    );

    expect(result).toEqual({
      _p_owner: '_User$u1',
      'data.score': { $lte: 5 },
    });
  });

  it('wraps a scalar used against an array field in $all', () => {
    expect(transformWhere('Post', { tags: 'featured' }, schema)).toEqual({
      tags: { $all: ['featured'] },
    });
  });

  it('recursively transforms logical query operators', () => {
    expect(
      transformWhere(
        'Post',
        {
          $or: [{ score: { $gt: 10 } }, { objectId: 'abc' }],
        },
        schema
      )
    ).toEqual({
      $or: [{ score: { $gt: 10 } }, { _id: 'abc' }],
    });
  });

  it('maps auth data subfields to legacy auth columns only for users', () => {
    expect(
      transformWhere('_User', { 'authData.google.id': 'g-123' }, schema)
    ).toEqual({ _auth_data_google: { $eq: 'g-123' } });
    expect(
      transformWhere('_User', { 'authData.google.id': 'g-123' }, schema)
    ).not.toHaveProperty('authData.google.id');
  });

  it('normalizes text search constraints and rejects malformed text searches', () => {
    expect(
      transformWhere(
        'Post',
        { title: { $text: { $search: { $term: 'mongo', $language: 'en' } } } },
        schema
      )
    ).toEqual({ $text: { $search: 'mongo', $language: 'en' } });

    expect(() =>
      transformWhere('Post', { title: { $text: { $search: { $term: 123 } } } }, schema)
    ).toThrow(Parse.Error);
  });

  it('converts a nearSphere query to a centerSphere constraint for counting', () => {
    expect(
      transformWhere(
        'Place',
        { location: { $nearSphere: { latitude: 10, longitude: 20 }, $maxDistance: 2 } },
        schema,
        true
      )
    ).toEqual({
      location: { $geoWithin: { $centerSphere: [[20, 10], 2] } },
    });

    expect(
      transformWhere(
        'Place',
        { location: { $nearSphere: { latitude: 10, longitude: 20 } } },
        schema
      )
    ).toEqual({ location: { $nearSphere: [20, 10] } });
  });

  it('rejects invalid query constraints', () => {
    expect(() => transformWhere('Post', { score: { $in: 4 } }, schema)).toThrow(
      'bad $in value'
    );
    expect(() => transformWhere('Post', { score: { $unknown: 4 } }, schema)).toThrow(
      'bad constraint: $unknown'
    );
    expect(() => transformWhere('Post', { score: { $regex: 4 } }, schema)).toThrow(
      'bad regex: 4'
    );
  });
});

describe('parseObjectToMongoObjectForCreate', () => {
  it('converts a Parse object to Mongo storage format', () => {
