    const result = parseObjectToMongoObjectForCreate(
      'Post',
      {
        objectId: 'post-1',
        name: 'Hello',
        createdAt,
        owner: { __type: 'Pointer', className: '_User', objectId: 'u1' },
        file: { __type: 'File', name: 'photo.png' },
        location: { __type: 'GeoPoint', latitude: 10, longitude: 20 },
        data: { nested: { score: 2 } },
        comments: { __type: 'Relation', className: 'Comment' },
        ignored: undefined,
