      schema
    );

    expect(result).toEqual({
      _id: 'post-1',
      name: 'Hello',
      _created_at: new Date(createdAt),
      _p_owner: '_User$u1',
      file: 'photo.png',
      location: [20, 10],
      data: { nested: { score: 2 } },
    });
  });

  it('creates the legacy ACL fields from read and write permissions', () => {
    const result = parseObjectToMongoObjectForCreate(
      'Post',
      {
        name: 'Private',
        _rperm: ['role:admin', 'user-1'],
        _wperm: ['role:admin'],
      },
      schema
    );

    expect(result._acl).toEqual({
      'role:admin': { w: true, r: true },
      'user-1': { r: true },
