    expect(result._rperm).toEqual(['role:admin', 'user-1']);
    expect(result._wperm).toEqual(['role:admin']);
  });

  it('rejects authData.id and nested keys containing Mongo operators or dots', () => {
    expect(() =>
      parseObjectToMongoObjectForCreate(
