describe('MongoStorageAdapter query and transaction helpers', () => {
  let adapter;

  beforeEach(() => {
    adapter = createAdapter();
  });

  it('maps read preference names and rejects unknown values', () => {
    expect(adapter._parseReadPreference('primary')).toBe('primary');
    expect(adapter._parseReadPreference('secondary_preferred')).toBe('secondaryPreferred');
    expect(adapter._parseReadPreference('NEAREST')).toBe('nearest');
    expect(adapter._parseReadPreference(null)).toBeNull();
    expect(() => adapter._parseReadPreference('local')).toThrow('Not supported read preference.');
  });

  it('converts parseable date strings recursively without changing other values', () => {
    const date = new Date('2024-01-01T00:00:00.000Z');
    const result = adapter._convertToDate({
      exact: date,
      stringDate: '2024-02-02T00:00:00.000Z',
      notDate: 'hello',
      nested: { number: 5 },
    });

    expect(result.exact).toBe(date);
    expect(result.stringDate).toEqual(new Date('2024-02-02T00:00:00.000Z'));
    expect(result.notDate).toBe('hello');
    expect(result.nested.number).toBe(5);
  });

  it('starts, commits and closes a transaction session', async () => {
    const session = {
      startTransaction: jest.fn(),
      commitTransaction: jest.fn().mockResolvedValue(),
      endSession: jest.fn(),
    };
    adapter.client = { startSession: jest.fn().mockReturnValue(session) };

    await expect(adapter.createTransactionalSession()).resolves.toBe(session);
    expect(session.startTransaction).toHaveBeenCalledTimes(1);

    await adapter.commitTransactionalSession(session);
    expect(session.commitTransaction).toHaveBeenCalledTimes(1);
    expect(session.endSession).toHaveBeenCalledTimes(1);
  });

  it('retries a transient transaction commit before ending the session', async () => {
    const transient = Object.assign(new Error('retry'), {
      hasErrorLabel: label => label === 'TransientTransactionError',
    });
    const session = {
      commitTransaction: jest
        .fn()
        .mockRejectedValueOnce(transient)
        .mockResolvedValueOnce(),
      endSession: jest.fn(),
    };

    await adapter.commitTransactionalSession(session);

    expect(session.commitTransaction).toHaveBeenCalledTimes(2);
    expect(session.endSession).toHaveBeenCalledTimes(1);
  });

  it('does not end a session when a non-transient commit fails', async () => {
    const failure = new Error('fatal');
    const session = {
      commitTransaction: jest.fn().mockRejectedValue(failure),
      endSession: jest.fn(),
    };

    await expect(adapter.commitTransactionalSession(session)).rejects.toBe(failure);
    expect(session.endSession).not.toHaveBeenCalled();
  });

  it('aborts and ends a transaction session', async () => {
    const session = {
      abortTransaction: jest.fn().mockResolvedValue(),
      endSession: jest.fn(),
    };

    await adapter.abortTransactionalSession(session);

    expect(session.abortTransaction).toHaveBeenCalledTimes(1);
    expect(session.endSession).toHaveBeenCalledTimes(1);
  });
});
