  it('atomically finds and updates an object and converts the returned document', async () => {
    collection._mongoCollection.findOneAndUpdate.mockResolvedValue({
      _id: 'p1',
      title: 'Updated',
      _p_owner: '_User$u1',
    });

    const result = await adapter.findOneAndUpdate(
      'Post',
      schema,
      { objectId: 'p1' },
      { title: 'Updated' }
    );

    expect(collection._mongoCollection.findOneAndUpdate).toHaveBeenCalledWith(
      { _id: 'p1' },
      { $set: { title: 'Updated' } },
      { returnDocument: 'after', session: undefined }
    );
    expect(result).toMatchObject({
      objectId: 'p1',
      title: 'Updated',
      owner: pointer,
    });
  });

  it('maps duplicate-key failures from findOneAndUpdate to a duplicate Parse error', async () => {
    collection._mongoCollection.findOneAndUpdate.mockRejectedValue({
      code: 11000,
      message: 'E11000 duplicate key error index: db.Post.$email_1 dup key',
    });

    await expect(
      adapter.findOneAndUpdate('Post', schema, {}, { title: 'Duplicate' })
    ).rejects.toMatchObject({
      code: Parse.Error.DUPLICATE_VALUE,
      userInfo: { duplicated_field: 'email' },
    });
  });

  it('performs an upsert with transformed query and update values', async () => {
    await adapter.upsertOneObject(
      'Post',
      schema,
      { objectId: 'p1' },
      { title: 'Upserted' },
      { id: 'session' }
