});

describe('MongoStorageAdapter typed reads', () => {
  let adapter;
  let schema;
  let collection;

  beforeEach(() => {
    adapter = makeAdapter({ maxTimeMS: 100, batchSize: 20 });
    schema = makeSchema();
    collection = {
      find: jest.fn(),
      count: jest.fn().mockResolvedValue(3),
      distinct: jest.fn(),
      aggregate: jest.fn(),
    };
    adapter._adaptiveCollection = jest.fn().mockResolvedValue(collection);
    adapter.createTextIndexesIfNeeded = jest.fn().mockResolvedValue();
  });

  it('transforms query, sort and projection keys and converts returned objects', async () => {
    collection.find.mockResolvedValue([
      {
        _id: 'p1',
        title: 'Hello',
        _p_owner: '_User$u1',
        _created_at: '2024-01-02T03:04:05.000Z',
        _rperm: ['user-1'],
        _wperm: ['role:admin'],
      },
    ]);

    const result = await adapter.find(
      'Post',
      schema,
      { objectId: 'p1', owner: pointer },
      {
        skip: 2,
        limit: 5,
        sort: { createdAt: -1 },
        keys: ['title', 'ACL'],
        readPreference: 'secondary',
        hint: { title: 1 },
        caseInsensitive: true,
        comment: 'read posts',
      }
    );

    expect(adapter.createTextIndexesIfNeeded).toHaveBeenCalledWith(
      'Post',
      { objectId: 'p1', owner: pointer },
      expect.objectContaining({ title: { type: 'String' } })
    );
    expect(collection.find).toHaveBeenCalledWith(
      { _id: 'p1', _p_owner: '_User$u1' },
      {
        skip: 2,
        limit: 5,
        sort: { _created_at: -1 },
        keys: { title: 1, _rperm: 1, _wperm: 1, _id: 0 },
        maxTimeMS: 100,
        batchSize: 20,
        readPreference: 'secondary',
        hint: { title: 1 },
        caseInsensitive: true,
        explain: undefined,
        comment: 'read posts',
      }
    );
    expect(result).toMatchObject({
      objectId: 'p1',
      title: 'Hello',
      owner: pointer,
      _rperm: ['user-1'],
      _wperm: ['role:admin'],
      createdAt: '2024-01-02T03:04:05.000Z',
    });
  });

  it('returns raw explain output without Parse conversion', async () => {
    const explainResult = { queryPlanner: { namespace: 'db.Post' } };
    collection.find.mockResolvedValue(explainResult);

    await expect(
      adapter.find('Post', schema, {}, { explain: 'queryPlanner' })
    ).resolves.toBe(explainResult);
  });

  it('rejects invalid explain values before querying', async () => {
    expect(() => adapter.find('Post', schema, {}, { explain: 'invalid' })).toThrow(
      'Invalid value for explain'
    );
    expect(collection.find).not.toHaveBeenCalled();
  });

  it('maps pointer distinct values and filters out null results', async () => {
    collection.distinct.mockResolvedValue(['_User$u1', null, '_User$u2']);

    await expect(
      adapter.distinct('Post', schema, { title: 'Hello' }, 'owner')
    ).resolves.toEqual([
      { __type: 'Pointer', className: '_User', objectId: 'u1' },
      { __type: 'Pointer', className: '_User', objectId: 'u2' },
    ]);
    expect(collection.distinct).toHaveBeenCalledWith('_p_owner', { title: 'Hello' });
  });

  it('counts using the transformed query and read preference', async () => {
    await expect(
      adapter.count('Post', schema, { owner: pointer }, 'PRIMARY_PREFERRED', false, { title: 1 }, 'count')
    ).resolves.toBe(3);

    expect(collection.count).toHaveBeenCalledWith(
      { _p_owner: '_User$u1' },
      {
        maxTimeMS: 100,
        readPreference: 'primaryPreferred',
        hint: { title: 1 },
        comment: 'count',
      }
    );
  });

  it('runs an aggregate pipeline with field and value transformations', async () => {
    collection.aggregate.mockResolvedValue([
      { _id: '_User$u1', total: 2, _p_owner: '_User$u1' },
    ]);

    const result = await adapter.aggregate(
      'Post',
      schema,
      [
        {
          $match: {
            owner: pointer,
            createdAt: { $gte: '2024-01-01T00:00:00.000Z' },
          },
        },
        { $group: { _id: '$owner', total: { $sum: 1 } } },
        { $project: { objectId: '$_id', owner: '$_p_owner', total: '$total' } },
      ],
      'SECONDARY',
      { title: 1 },
      false,
      'aggregate-comment'
    );

    expect(collection.aggregate).toHaveBeenCalledWith(
      [
        {
          $match: {
            _p_owner: pointer,
            _created_at: { $gte: new Date('2024-01-01T00:00:00.000Z') },
          },
        },
        { $group: { _id: '$_p_owner', total: { $sum: 1 } } },
        { $project: { _id: '$_id', _p_owner: '$_p_owner', total: '$total' } },
      ],
      {
        readPreference: 'secondary',
        maxTimeMS: 100,
        batchSize: 20,
        hint: { title: 1 },
        explain: false,
        comment: 'aggregate-comment',
      }
    );
    expect(result).toEqual([
      {
        objectId: 'u1',
        total: 2,
        owner: pointer,
      },
    ]);
  });

  it('validates aggregate explain values', () => {
    expect(() => adapter.aggregate('Post', schema, [], null, null, 'bad')).toThrow(
      'Invalid value for explain'
    );
  });

  it('forwards _rawFind directly to the wrapped collection with configured limits', async () => {
    collection.find.mockResolvedValue([{ _id: 'p1' }]);

    await expect(adapter._rawFind('Post', { title: 'Hello' })).resolves.toEqual([{ _id: 'p1' }]);
    expect(collection.find).toHaveBeenCalledWith(
      { title: 'Hello' },
      { maxTimeMS: 100, batchSize: 20 }
    );
  });
});

describe('MongoStorageAdapter indexing', () => {
  let adapter;
  let schema;
  let rawCollection;

  beforeEach(() => {
    adapter = makeAdapter();
    schema = makeSchema();
    rawCollection = {
      createIndex: jest.fn().mockResolvedValue('index'),
      createIndexes: jest.fn().mockResolvedValue(['index']),
      indexes: jest.fn().mockResolvedValue([]),
      dropIndex: jest.fn().mockResolvedValue(),
      dropIndexes: jest.fn().mockResolvedValue(),
    };
    adapter._adaptiveCollection = jest.fn().mockResolvedValue({
      _mongoCollection: rawCollection,
      _ensureSparseUniqueIndexInBackground: jest.fn().mockResolvedValue('unique-index'),
    });
  });

  it('creates a compound index with pointer field names, ordering and options', async () => {
    await adapter.ensureIndex(
      'Post',
      schema,
      ['owner', 'title'],
      'owner_title',
      true,
      {
        indexType: -1,
        ttl: 3600,
        sparse: false,
        partialFilterExpression: { title: { $exists: true } },
      }
    );

    expect(rawCollection.createIndex).toHaveBeenCalledWith(
      { _p_owner: -1, title: -1 },
      {
        background: true,
        sparse: false,
        collation: { locale: 'en_US', strength: 2 },
        name: 'owner_title',
        expireAfterSeconds: 3600,
        partialFilterExpression: { title: { $exists: true } },
      }
    );
  });

  it('translates duplicate values while ensuring field uniqueness', async () => {
    const wrapped = await adapter._adaptiveCollection('Post');
    wrapped._ensureSparseUniqueIndexInBackground.mockRejectedValueOnce({ code: 11000 });

    await expect(adapter.ensureUniqueness('Post', schema, ['owner'])).rejects.toMatchObject({
      code: Parse.Error.DUPLICATE_VALUE,
      message: 'Tried to ensure field uniqueness for a class that already has duplicates.',
    });
    expect(wrapped._ensureSparseUniqueIndexInBackground).toHaveBeenCalledWith({ _p_owner: 1 });
  });

  it('creates the legacy auth data uniqueness index', async () => {
    await adapter.ensureAuthDataUniqueness('google');

    expect(adapter._adaptiveCollection).toHaveBeenCalledWith('_User');
    expect(rawCollection.createIndex).toHaveBeenCalledWith(
      { '_auth_data_google.id': 1 },
      {
        unique: true,
        sparse: true,
        background: true,
        name: '_auth_data_google_id',
      }
    );
  });

  it('ignores an auth-data index that already exists with the same or different options', async () => {
    rawCollection.createIndex.mockRejectedValueOnce({ code: 85 });
    await expect(adapter.ensureAuthDataUniqueness('google')).resolves.toBeUndefined();

    rawCollection.createIndex.mockRejectedValueOnce({ code: 86 });
    await expect(adapter.ensureAuthDataUniqueness('google')).resolves.toBeUndefined();
  });

  it('maps auth-data duplicate failures to a duplicate Parse error', async () => {
    rawCollection.createIndex.mockRejectedValueOnce({ code: 11000 });

    await expect(adapter.ensureAuthDataUniqueness('google')).rejects.toMatchObject({
      code: Parse.Error.DUPLICATE_VALUE,
    });
  });

  it('delegates raw index lifecycle operations and performs no-op initialization', async () => {
    await expect(adapter.createIndex('Post', { title: 1 })).resolves.toBe('index');
    await expect(adapter.createIndexes('Post', [{ key: { title: 1 } }])).resolves.toEqual([
      'index',
    ]);
    await expect(adapter.getIndexes('Post')).resolves.toEqual([]);
    await expect(adapter.dropIndex('Post', 'title_1')).resolves.toBeUndefined();
    await expect(adapter.dropAllIndexes('Post')).resolves.toBeUndefined();
    await expect(adapter.performInitialization()).resolves.toBeUndefined();

    expect(rawCollection.createIndex).toHaveBeenCalledWith({ title: 1 });
    expect(rawCollection.createIndexes).toHaveBeenCalledWith([{ key: { title: 1 } }]);
    expect(rawCollection.dropIndex).toHaveBeenCalledWith('title_1');
    expect(rawCollection.dropIndexes).toHaveBeenCalledTimes(1);
  });
});
